    var Tm = T >= 120 ? (T / 60).toFixed(1) + ' min' : T.toFixed(2) + ' s';
    outT(Tm, sys === 'tunnel' ? 'the same for every tunnel' : sys === 'piston' ? 'T ∝ 1/√γ' : sys === 'utube' ? 'T = 2π√(ℓ/2g)' : 'T = 2π√(h/g)');
